package com.vsmartcard.acardemulator.emulators.mrtd;
import java.io.*;
import java.security.*;
import java.security.spec.PKCS8EncodedKeySpec;
import org.bouncycastle.jce.provider.BouncyCastleProvider;
import org.bouncycastle.asn1.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static com.vsmartcard.acardemulator.emulators.mrtd.CardBytes.*;
public class TerminalAuthorizationTest {
 static byte[] file(String type,String name)throws Exception{try(InputStream in=TerminalAuthorizationTest.class.getResourceAsStream("/mrtd/ta-"+type+"-"+name)){assertNotNull(in);ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[1024];int n;while((n=in.read(b))>=0)out.write(b,0,n);return out.toByteArray();}}
 static byte[] ref(String name){return tlv(0x83,name.getBytes(java.nio.charset.StandardCharsets.US_ASCII));}
 static void refused(int sw,Operation operation)throws Exception{try{operation.run();fail("Expected refusal");}catch(Status e){assertEquals(sw,e.sw);}}
 interface Operation{void run()throws Exception;}
 static void chain(TerminalAuthorization t,String type,String leaf)throws Exception{t.execute(0x22,0x81,0xB6,ref("UTTESTCVCA00001"),0);t.execute(0x2A,0,0xBE,objects(file(type,"dv.cvc")).get(0).value,0);t.execute(0x22,0x81,0xB6,ref("UTTESTDV00001"),0);t.execute(0x2A,0,0xBE,objects(file(type,leaf+".cvc")).get(0).value,0);t.execute(0x22,0x81,0xA4,ref("UTTESTIS00001"),0);}
 static byte[] signature(String type,byte[] data)throws Exception{Signature sign=Signature.getInstance(type.equals("ec")?"SHA256withECDSA":"SHA256withRSA",new BouncyCastleProvider());sign.initSign(KeyFactory.getInstance(type.equals("ec")?"EC":"RSA",new BouncyCastleProvider()).generatePrivate(new PKCS8EncodedKeySpec(file(type,"terminal.pk8"))));sign.update(data);byte[] result=sign.sign();if(type.equals("ec")){ASN1Sequence s=(ASN1Sequence)new ASN1InputStream(result).readObject();result=concat(fixed(DERInteger.getInstance(s.getObjectAt(0)).getPositiveValue().toByteArray()),fixed(DERInteger.getInstance(s.getObjectAt(1)).getPositiveValue().toByteArray()));}return result;}
 static byte[] fixed(byte[] b){if(b.length==33&&b[0]==0)b=slice(b,1,33);assertTrue(b.length<=32);byte[] out=new byte[32];System.arraycopy(b,0,out,32-b.length,b.length);return out;}
 static byte[] id(){return hex("44323331343538393037");}static byte[] hash(){return new byte[32];}
 static void authenticate(TerminalAuthorization t,String type)throws Exception{byte[] challenge=t.execute(0x84,0,0,new byte[0],8);t.execute(0x82,0,0,signature(type,concat(id(),challenge,hash())),0);}
 @Test public void TARequiresCAAndFreshChallenge()throws Exception{for(String type:new String[]{"ec","rsa"}){TerminalAuthorization t=new TerminalAuthorization(file(type,"root.cvc"));refused(0x6985,()->t.execute(0x22,0x81,0xB6,ref("UTTESTCVCA00001"),0));t.afterCA(id(),hash());chain(t,type,"valid");refused(0x6985,()->t.execute(0x82,0,0,new byte[64],0));assertFalse(t.allows(3));}}
 @Test public void certificateChainAndEffectiveDGPermissions()throws Exception{for(String type:new String[]{"ec","rsa"})for(String leaf:new String[]{"valid","dg3"}){TerminalAuthorization t=new TerminalAuthorization(file(type,"root.cvc"));t.afterCA(id(),hash());chain(t,type,leaf);assertFalse(t.allows(3));authenticate(t,type);assertTrue(t.allows(3));assertEquals(leaf.equals("valid"),t.allows(4));assertTrue(t.authenticated());t.clear();assertFalse(t.allows(3));assertFalse(t.authenticated());}}
 @Test public void invalidAndExpiredCertificatesCannotAuthorize()throws Exception{for(String type:new String[]{"ec","rsa"})for(String leaf:new String[]{"expired","bad-cert"}){TerminalAuthorization t=new TerminalAuthorization(file(type,"root.cvc"));t.afterCA(id(),hash());refused(leaf.equals("expired")?0x6982:0x6300,()->chain(t,type,leaf));assertFalse(t.allows(3));}}
 @Test public void untrustedSigningKeyIsRejectedEvenWithTrustedIssuerName()throws Exception{for(String type:new String[]{"ec","rsa"}){TerminalAuthorization t=new TerminalAuthorization(file(type,"root.cvc"));t.afterCA(id(),hash());t.execute(0x22,0x81,0xB6,ref("UTTESTCVCA00001"),0);refused(0x6300,()->t.execute(0x2A,0,0xBE,objects(file(type,"untrusted.cvc")).get(0).value,0));assertFalse(t.allows(3));}}
 @Test public void challengeIsSingleUseAndReplayRevokesPermissions()throws Exception{for(String type:new String[]{"ec","rsa"}){TerminalAuthorization t=new TerminalAuthorization(file(type,"root.cvc"));t.afterCA(id(),hash());chain(t,type,"valid");byte[] c=t.execute(0x84,0,0,new byte[0],8),s=signature(type,concat(id(),c,hash()));t.execute(0x82,0,0,s,0);assertTrue(t.allows(3));refused(0x6985,()->t.execute(0x82,0,0,s,0));assertFalse(t.allows(3));}}
 @Test public void newChallengeInvalidatesOldSignature()throws Exception{for(String type:new String[]{"ec","rsa"}){TerminalAuthorization t=new TerminalAuthorization(file(type,"root.cvc"));t.afterCA(id(),hash());chain(t,type,"valid");byte[] c=t.execute(0x84,0,0,new byte[0],8),s=signature(type,concat(id(),c,hash()));t.execute(0x84,0,0,new byte[0],8);refused(0x6300,()->t.execute(0x82,0,0,s,0));assertFalse(t.allows(3));}}
 @Test public void signatureBindsIdentifierAndCAEphemeralKeyHash()throws Exception{for(String type:new String[]{"ec","rsa"})for(int changed:new int[]{0,1}){TerminalAuthorization t=new TerminalAuthorization(file(type,"root.cvc"));t.afterCA(id(),hash());chain(t,type,"valid");byte[] c=t.execute(0x84,0,0,new byte[0],8),wrongID=id(),wrongHash=hash();if(changed==0)wrongID[0]^=1;else wrongHash[0]^=1;byte[] s=signature(type,concat(wrongID,c,wrongHash));refused(0x6300,()->t.execute(0x82,0,0,s,0));assertFalse(t.allows(4));}}
 @Test public void newCAClearsPreviousTerminalRights()throws Exception{for(String type:new String[]{"ec","rsa"}){TerminalAuthorization t=new TerminalAuthorization(file(type,"root.cvc"));t.afterCA(id(),hash());chain(t,type,"valid");authenticate(t,type);assertTrue(t.allows(4));t.afterCA(id(),hash());assertFalse(t.allows(3));assertFalse(t.allows(4));}}
}
